={{ {
  statement: [
    "MATCH (doc:Document)-[:DOCUMENTS]->(embassy:Embassy)",
    "      -[:LOCATED_IN]->(country:Country)",
    "WHERE toLower(country.name) = toLower(trim($country))",
    "RETURN embassy.name AS embassy,",
    "       embassy.address AS address,",
    "       embassy.city AS city,",
    "       country.name AS country,",
    "       doc.source_url AS source_url,",
    "       embassy.retrieved_at AS retrieved_at",
    "ORDER BY embassy"
  ].join("\n"),
  parameters: {
    country: $json.country
  }
} }}

parameters.jsCode:
if ($json.errors?.length) {
  throw new Error(
    'Neo4j-fejl: ' +
    $json.errors.map(error => error.message).join('; ')
  );
}

const data = $json.data;

if (!Array.isArray(data?.fields) || !Array.isArray(data?.values)) {
  throw new Error('Neo4j returnerede et uventet format.');
}

const results = data.values.map(row =>
  Object.fromEntries(
    data.fields.map((field, index) => [field, row[index]])
  )
);

return {
  json: {
    found: results.length > 0,
    count: results.length,
    results,
    message: results.length > 0
      ? 'Ambassadeoplysninger fundet i den gemte graf. Brug source_url som kilde. retrieved_at er indsamlingsdatoen.'
      : 'Der blev ikke fundet ambassadeoplysninger for det valgte land i databasen. Det betyder ikke, at ambassaden ikke findes.'
  }
};
